BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('preview_table_rows', 'v1'), ('research_web', 'v3'))) <> 2 THEN
        RAISE EXCEPTION 'Expected the previous tool versions (''preview_table_rows'', ''v1''), (''research_web'', ''v3'')';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name = 'preview_table_rows' AND version = 'v2') OR (tool_name = 'research_web' AND version = 'v4')) THEN
        RAISE EXCEPTION 'The fixed income and Feature 04 onboarded tool versions are already registered';
    END IF;
END
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
