)
SELECT tool_name, tool_family, tool_type, next.purpose, next.input_schema::jsonb, output_schema,
       execution_type, handler_name, default_output_rows, max_output_rows,
       max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
       timeout_seconds, max_output_bytes, max_llm_result_rows,
       max_llm_result_bytes, max_llm_result_tokens,
       requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
       tool_specific_limits || '{"design":"EXEC.md EXEC-ONBOARD-1","preview_objects":"ten approved objects; the ORDER BY of each is app/tools/preview.py ORDERING and public.ai_preview_table_rows (20261020_001)","registry_state":"registered from code (market-ai-orc) under the dev flags, inactive here"}'::jsonb, next.version, false
FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('preview_table_rows', 'v1', 'v2', '{"additionalProperties":false,"properties":{"table_name":{"description":"One of the ten approved market-data tables.","enum":["Feature_01_Stock_Daily","Feature_02_Broker_Rolling","Feature_03_Stock_Broker_Daily","IDX_Broker_Profile","IDX_Broker_Summary","IDX_Stock_Universe","Price_Stock_Indonesia_IDX","Price_Fixed_Income_Final","Universe_Fixed_income","Feature_04_Technical_Indicator"],"type":"string"}},"required":["table_name"],"type":"object"}',
     'Return up to 20 example rows (all columns) from one of ten approved market-data tables, in a fixed deterministic order stated in the result. No filters, offsets, custom limits, or pagination. Example records only, not a complete or representative dataset and not an analysis.'),
    ('research_web', 'v3', 'v4', '{"additionalProperties":false,"properties":{"expected_shape":{"anyOf":[{"enum":["FACT","NUMBER","EVENT","SERIES","LIST"],"type":"string"},{"type":"null"}],"description":"The shape the answer should have, or null when not known."},"need":{"description":"What to find, in words, e.g. ''nilai ekspor Indonesia per tahun sejak 2018''. Limits: at most 500 characters; at least 3 characters.","type":"string"},"purpose":{"description":"CITE: values to state in the answer; CONTEXT: background for an analysis of the data.","enum":["CITE","CONTEXT"],"type":"string"},"subjects":{"description":"Companies or entities the same need is asked about, one lookup each; empty for one need. Limits: at most 30 items.","items":{"type":"string"},"type":"array"}},"required":["need","purpose","expected_shape","subjects"],"type":"object"}',
     'Information that is not in the market database, from the web, for context or when the database lacks it: a fact, a figure, an event with its dates, a series over periods (for example yearly exports) or a list (for example the banks a group controls). Give one need in words, its purpose (CITE a value in the answer, CONTEXT for an analysis) and the expected shape when you know it; the same need about several companies is one call with them as subjects. The web governor searches, keeps only items quoted verbatim from their sources, labels false conflicts (different periods, definitions, units or releases) and, for a real conflict, the version it prefers (chosen_by_ai) with every version kept. Never use it for prices, yields, volumes, flows, indicators or any figure the database holds; a web number describes and is never an input of a calculation, while an event date may set an analysis period. A run has a limited web budget: ask for what the answer needs. Each item has a ref: cite a number as {{<ref>.value_as_written}} (as its source writes it) or {{<ref>.value}} (the value at full scale), and a list or a short value as {{<ref>.value}}; the text shows the value without a link, and its source page is listed in the answer''s Sources panel. A fact''s statement is never inserted: say it in the reader''s language, in your own words, and put {{<ref>.value}} right after it, which shows nothing in the text and records the statement''s source; a figure the statement or its quote gives ("5,1%") may be written in those words, and it is checked against that quote. An attribute the database''s reference tables hold (sector, industry, company profile) is read with lookup_reference; this tool is refused for it until those tables have been read.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'preview_table_rows' AND version = 'v2') OR (tool_name = 'research_web' AND version = 'v4'))) <> 2 THEN
