    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'preview_table_rows' AND version = 'v2' AND input_schema::text LIKE '%Feature_04_Technical_Indicator%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'research_web' AND version = 'v4' AND purpose::text LIKE '%yields%') THEN
        RAISE EXCEPTION 'The fixed income and Feature 04 onboarded contracts are not in the registered rows';
    END IF;
END
$verify$;

COMMIT;
